files.onyx-pkg.kdl:
package {
    name "{{name}}"
    author "{{author}}"
    url ""
    description "{{description}}"
    version "0.1.0"
}

config {
    dependency_source_path "./lib"
    dependency_binary_path "./bin"
}

dependencies {
    "odit_sdk" "1.2.0" git="https://github.com/pigeonowo/odit_onyx_sdk"
}

lsp {
    mode "project"
    source_files "src/main.onyx"
    include_dirs ""
    working_dir "."
}

src.main.onyx:
#load "./../lib/packages"

use core { tprintf }
use odit.abi
use odit.sdk

@sdk.Plugin.{
    id             = "user.{{name}}",
    title          = "{{title}}",
    version        = "0.1.0",
    default_slot   = 0,
    default_width  = 360.0f,
    default_height = 240.0f,
    event_mask     = 0xFFFFFFFF, // Subscribe to all IDE events
    allow_multiple = false,
}
PluginState :: struct {
    clicks: u32;
}

@sdk.PluginInit
init :: (self: &PluginState, window_id: u32) -> i32 {
    sdk.register_command("{{name}}.hello", "{{title}}: Say Hello", "");
    sdk.register_setting("{{name}}.greeting", "{{title}}: Greeting", .String, "Hello from {{title}}!");
    return 0;
}

@sdk.PluginEvent
on_event :: (self: &PluginState, window_id: u32, event: sdk.Event) {
    switch event {
        case .Command as cmd {
            if cmd == "{{name}}.hello" {
                self.clicks += 1;
                msg := sdk.get_setting("{{name}}.greeting", context.temp_allocator);
                sdk.notify(.Info, msg if msg.count > 0 else "Hello!");
            }
        }
        case _ {}
    }
}

@sdk.PluginRender
render :: (self: &PluginState, window_id: u32, ctx: &abi.FrameContext) {
    pad: f32 = 12.0f;
    greeting := sdk.get_setting("{{name}}.greeting", context.temp_allocator);
    sdk.draw_text(pad, pad, greeting if greeting.count > 0 else "Hello!", 15.0f, sdk.theme_color(.TextPrimary), .Bold);
    sdk.draw_text(pad, pad + 26.0f, tprintf("Clicks: {}", self.clicks), 13.0f, sdk.theme_color(.TextSecondary));

    sdk.on_click(1, pad, pad + 54.0f, 140.0f, 32.0f, "Click Me", .Primary) {
        self.clicks += 1;
    };
}

files.build.onyx:
// =============================================================================
// ODIT Plugin Build & Install Script (`onyx run build.onyx [-- install|dev]`)
// =============================================================================
//   onyx run build.onyx            -> compiles build/{{name}}.wasm
//   onyx run build.onyx -- install -> compiles & installs to ~/.config/odit/plugins/{{name}}.wasm
//   onyx run build.onyx -- dev     -> compiles & copies to .odit/plugins/{{name}}.wasm

use core { package, os, printf, println }

PLUGIN_NAME :: "{{name}}"

resolve_onyx :: () -> str {
    if op := os.env("ONYX_PATH", context.temp_allocator); op && op->unwrap().count > 0 {
        cand := core.tprintf("{}/bin/onyx", op->unwrap());
        if os.file_exists(cand) do return cand;
    }
    if h := os.env("HOME", context.temp_allocator); h && h->unwrap().count > 0 {
        cand := core.tprintf("{}/.onyx/bin/onyx", h->unwrap());
        if os.file_exists(cand) do return cand;
    }
    return "onyx";
}

main :: (args: [] cstr) {
    do_install := false;
    do_dev     := false;
    for i in 0 .. args.count {
        a := core.string.from_cstr(args[i]);
        if str.equal(a, "install") do do_install = true;
        if str.equal(a, "dev")     do do_dev     = true;
    }

    onyx_bin := resolve_onyx();
    if !os.file_exists("lib/packages.onyx") {
        println("[build] Syncing dependencies (onyx pkg sync)...");
        _ := os.command()->path(onyx_bin)->args(.["pkg", "sync"])->output();
    }

    os.Directory.create("build");
    out_wasm := core.tprintf("build/{}.wasm", PLUGIN_NAME);

    printf("[build] Compiling {} -> {}...\n", "src/main.onyx", out_wasm);
    cmd := os.command()->path(onyx_bin)->args(.[
        "build", "-r", "js", "--wasm-mvp", "-o", out_wasm, "src/main.onyx"
    ]);
    switch cmd->output() {
        case .Ok {
            js_path := core.tprintf("{}.js", out_wasm);
            if os.file_exists(js_path) do os.remove_file(js_path);
            printf("[build] Built {}\n", out_wasm);
        }
        case .Err as err {
            printf("[build] Compilation failed:\n{}\n", err.output);
            os.exit(1);
        }
    }

    if do_install {
        if h := os.env("HOME", context.temp_allocator); h && h->unwrap().count > 0 {
            cfg := core.tprintf("{}/.config", h->unwrap());
            od  := core.tprintf("{}/odit", cfg);
            pd  := core.tprintf("{}/plugins", od);
            if !os.Directory.exists(cfg) do os.Directory.create(cfg);
            if !os.Directory.exists(od)  do os.Directory.create(od);
            if !os.Directory.exists(pd)  do os.Directory.create(pd);
            dst := core.tprintf("{}/{}.wasm", pd, PLUGIN_NAME);
            data := os.get_contents(out_wasm);
            if data.count > 0 && os.File.write_contents(dst, data) {
                printf("[install] Installed -> {}\n", dst);
                println("[install] In ODIT, press Ctrl+P -> 'Plugins: Reload All .wasm Plugins'!");
            } else {
                println("[install] Failed to copy plugin binary.");
                os.exit(1);
            }
        }
    }

    if do_dev {
        os.Directory.create(".odit");
        os.Directory.create(".odit/plugins");
        dst := core.tprintf(".odit/plugins/{}.wasm", PLUGIN_NAME);
        data := os.get_contents(out_wasm);
        if data.count > 0 && os.File.write_contents(dst, data) {
            printf("[dev] Installed workspace plugin -> {}\n", dst);
        }
    }
}
